216:     if (AgenticOrchestrator.matchesAny(lower, AgenticOrchestrator.SHADOW_KEYWORDS.darkAversion))
217:       return { drive: 'communion', polarity: 'sto', shadowKeyword: 'DarkAverted' };
218:     if (AgenticOrchestrator.matchesAny(lower, AgenticOrchestrator.SHADOW_KEYWORDS.goldenAddiction))
219:       return { drive: 'eros', polarity: 'neutral', shadowKeyword: 'GoldenAddicted' };
220:     if (AgenticOrchestrator.matchesAny(lower, AgenticOrchestrator.SHADOW_KEYWORDS.goldenAllergy))
221:       return { drive: 'agape', polarity: 'neutral', shadowKeyword: 'GoldenAverted' };
222:     return null;
223:   }
