427:   /**
428:    * Fallback mode: use module content when available, FallbackProvider otherwise.
429:    * When a module is available, presents real assessment tasks (n-back, dilemmas,
430:    * emotion identification, etc.) as narrative challenges and evaluates responses
431:    * using the module's drive probes. Also detects shadow patterns and computes
432:    * altitude shifts from consistent healthy patterns.
433:    */
434:   private async runFallback(line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
435:     // CHECK: If we have an assessment module, use it for a real assessment
436:     if (this.module) {
437:       return this.runModuleAssessment(line, stage, now);
438:     }
439: 
440:     // Original generic fallback when no module is available
441:     const fallback = getFallback(this.encounter.modality, line, stage);
442:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
443:     const holonName = holon?.name ?? 'A presence';
444:     const holonRole = holon?.narrativeRole ?? 'guide';
