454:         questionText = fallback.prompt ?? 'What moved you to act?';
455:         options = [
456:           { label: 'Reflect deeply', description: 'Consider the question from multiple angles' },
457:           { label: 'Respond instinctively', description: 'Trust your first impulse' },
458:           { label: 'Sit with it', description: 'Allow the question to remain open' },
459:           { label: 'Challenge the premise', description: 'Question the foundation of what was asked' },
460:         ];
461:         break;
462:       case 'ScenarioChoice':
463:         narrativeIntro = `${holonName} confronts you. The air is tense. A choice must be made.`;
464:         questionText = fallback.scenario ?? 'A crossroads appears. Each path carries weight.';
465:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
466:         break;
467:       case 'Strategic':
468:         narrativeIntro = `The war-table is spread before you. ${holonName} surveys the terrain. Three routes. Limited forces.`;
469:         questionText = fallback.scenario ?? fallback.prompt ?? 'Resources are limited. The map shows three routes to the objective.';
470:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
471:         break;
472:       case 'Embodied':
473:         narrativeIntro = `The war-drums begin. ${holonName} guides you. Your body knows this rhythm.`;
474:         questionText = fallback.prompt ?? 'Close your eyes. Where do you feel tension in your body right now?';
475:         options = [
476:           { label: 'Follow the rhythm', description: 'Let the drum guide your body' },
477:           { label: 'Resist the beat', description: 'Fight against the pull' },
478:           { label: 'Breathe into it', description: 'Allow the sensation to move through you' },
479:           { label: 'Still yourself', description: 'Find the stillness within the movement' },
480:         ];
481:         break;
482:       case 'SocialCooperative':
483:         narrativeIntro = `${holonName} looks to you. Others wait for direction. The group needs your word.`;
484:         questionText = fallback.scenario ?? 'The scouts look to you. The path splits — one leads through danger, the other through uncertainty.';
485:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
486:         break;
487:       case 'ImmersiveRPG':
488:         narrativeIntro = `The world stretches before you. ${holonName} appears — ${holonRole} of this domain. What calls?`;
489:         questionText = fallback.prompt ?? 'The world stretches before you. A path winds through unfamiliar terrain. Something waits ahead.';
490:         options = [
491:           { label: 'Press forward', description: 'Step into the unknown' },
492:           { label: 'Survey the area', description: 'Gather information first' },
493:           { label: 'Seek shelter', description: 'Find safety before advancing' },
494:           { label: 'Call out', description: 'Announce your presence' },
495:         ];
496:         break;
497:       default:
498:         narrativeIntro = `${holonName} presents a challenge. The moment demands clarity.`;
499:         questionText = fallback.prompt ?? fallback.framing ?? 'Focus. The moment demands clarity.';
500:         options = [
