508: 
509:     const defaultOpts = [
510:       { label: 'Act decisively', description: 'Take the direct approach' },
511:       { label: 'Observe first', description: 'Gather more information' },
512:       { label: 'Seek alliance', description: 'Find strength in others' },
513:       { label: 'Deceive and maneuver', description: 'Use misdirection to your advantage' },
514:     ];
515:     while (options.length < 4) {
516:       const extra = defaultOpts[options.length];
517:       if (extra) options.push(extra);
518:       else break;
519:     }
520: 
521:     const fullPrompt = `${narrativeIntro}\n\n${questionText}`;
522: 
523:     const askParams: AskUserQuestionParams = {
524:       questions: [{
525:         question: fullPrompt,
526:         header: encounterModality,
527:         options,
