536: 
537:     const evaluated = this.evaluateFallbackResponse(narrativeSummary);
538: 
539:     const fallbackParams = {
540:       passed: evaluated.passed,
541:       feedback: evaluated.feedback,
542:       polarityDirection: evaluated.polarityDirection,
543:       driveScores: evaluated.driveScores,
544:       driveSignals: evaluated.driveSignals,
545:       narrativeSummary: typeof narrativeSummary === 'string' ? narrativeSummary : 'The player engaged with the encounter.',
546:     };
547: 
548:     const finalResult = this.createAssessmentResult(evaluated.passed, {}, evaluated.driveScores);
549:     const outcome = this.finalizeEncounter(fallbackParams, now);
