853:   /**
854:    * Select the best assessment task from the module based on encounter modality.
855:    */
856:   private selectTaskForModality(module: StageAssessment, modality: Modality): AssessmentTask {
857:     // Preferred task types for each modality, with fallback chains
858:     // If the preferred types aren't available in the module, we try broader types
859:     const modalityFallbackChain: Record<string, readonly TaskType[]> = {
860:       Deterministic: ['n_back', 'stroop', 'go_no_go', 'hold', 'reaction_time', 'rhythm'],
861:       LanguageReflective: ['llm_dialogue', 'self_report', 'emotion_identification', 'scenario'],
862:       ScenarioChoice: ['dilemma', 'scenario', 'emotion_identification', 'self_report'],
863:       Embodied: ['hold', 'rhythm', 'imitation', 'reaction_time', 'go_no_go'],
864:       Strategic: ['pattern_prediction', 'value_ranking', 'n_back', 'stroop'],
865:       SocialCooperative: ['cooperation', 'dilemma', 'emotion_identification', 'scenario', 'self_report'],
866:       ImmersiveRPG: ['scenario', 'dilemma', 'llm_dialogue', 'emotion_identification', 'self_report'],
867:     };
868: 
869:     const chain = modalityFallbackChain[modality] ?? ['n_back', 'scenario', 'self_report'];
870: 
871:     // Walk the fallback chain: first match wins
872:     for (const prefType of chain) {
873:       const match = module.tasks.find(t => t.type === prefType);
874:       if (match) return match;
875:     }
876: 
877:     // CRITICAL FIX: When no task type matches the modality's preference chain,
878:     // generate a modality-appropriate generic task instead of falling to tasks[0].
879:     // This prevents Cognitive modules (which have only n_back/pattern/go_nogo) from
880:     // showing n-back when ScenarioChoice modality is requested.
881:     return this.generateModalityFallbackTask(modality, module);
882:   }
