886:    * doesn't have any of the preferred task types. This ensures ScenarioChoice
887:    * always shows a dilemma, ImmersiveRPG always shows a scenario, etc.
888:    */
889:   private generateModalityFallbackTask(modality: Modality, module: StageAssessment): AssessmentTask {
890:     const prefix = `${module.line.toLowerCase()}-${module.stage.toLowerCase()}`;
891:     // Inject stage into all generated task parameters so TaskRenderers can use it for difficulty scaling
892:     const stage = module.stage;
893:     switch (modality) {
894:       case 'ScenarioChoice':
895:       case 'ImmersiveRPG':
896:         return {
897:           id: `generic-dilemma-${prefix}`,
898:           type: 'dilemma',
899:           description: `A developmental dilemma at the ${module.stage} stage of ${module.line} development`,
900:           parameters: { dilemmaType: 'developmental', choices: 4, stage, line: module.line },
901:           measures: ['depth', 'coherence'],
902:         };
903:       case 'LanguageReflective':
904:         return {
905:           id: `generic-self-report-${prefix}`,
906:           type: 'self_report',
907:           description: `Self-inquiry reflection at the ${module.stage} stage of ${module.line} development`,
908:           parameters: { stage },
909:           measures: ['depth', 'metacognition'],
910:         };
911:       case 'SocialCooperative':
912:         return {
913:           id: `generic-cooperation-${prefix}`,
914:           type: 'cooperation',
915:           description: `Cooperative dynamics at the ${module.stage} stage of ${module.line} development`,
916:           parameters: { stage },
917:           measures: ['depth', 'coherence'],
918:         };
919:       case 'Embodied':
920:         return {
921:           id: `generic-hold-${prefix}`,
922:           type: 'hold',
923:           description: `Attentional hold at the ${module.stage} stage of ${module.line} development`,
924:           parameters: { items: 3, holdDurationMs: 5000, stage },
925:           measures: ['accuracy', 'consistency'],
926:         };
927:       case 'Strategic':
928:         return {
929:           id: `generic-pattern-${prefix}`,
930:           type: 'pattern_prediction',
931:           description: `Pattern recognition at the ${module.stage} stage of ${module.line} development`,
932:           parameters: { disks: 3, attempts: 4, stage },
933:           measures: ['accuracy', 'complexity_handled'],
934:         };
935:       case 'Deterministic':
936:       default:
937:         return module.tasks[0] ?? {
938:           id: `generic-nback-${prefix}`,
939:           type: 'n_back',
940:           description: `Working memory challenge at the ${module.stage} stage of ${module.line} development`,
941:           parameters: { n: 2, trials: 12, stage },
942:           measures: ['accuracy', 'response_time'],
943:         };
944:     }
945:   }
