61: /**
62:  * Compute confidence in the pass/fail determination.
63:  * Formula: distance * consistency * trialFactor
64:  *   - distance: normalized distance of weighted score from threshold
65:  *   - consistency: 1 - variance of dimension scores across trials
66:  *   - trialFactor: min(1, trials.length / 6) - more trials = more confidence
67:  */
68: export function computeConfidence(
69:   trials: readonly TrialResult[],
70:   passThreshold: number,
71: ): number {
72:   if (trials.length === 0) return 0;
73: 
74:   // Compute weighted score across all trials (average of all dimensions present)
75:   const trialScores: number[] = [];
76:   for (const trial of trials) {
77:     const values = Object.values(trial.dimensions).filter(
78:       (v): v is number => v !== undefined,
79:     );
80:     if (values.length > 0) {
81:       trialScores.push(values.reduce((a, b) => a + b, 0) / values.length);
82:     }
83:   }
84: 
85:   if (trialScores.length === 0) return 0;
86: 
87:   const mean = trialScores.reduce((a, b) => a + b, 0) / trialScores.length;
88: 
89:   // distance: how far from the threshold (normalized 0-1)
90:   const distance = Math.min(1, Math.abs(mean - passThreshold));
91: 
92:   // consistency: 1 - variance (clamped to 0-1)
93:   const variance =
94:     trialScores.length > 1
95:       ? trialScores.reduce((sum, s) => sum + (s - mean) ** 2, 0) / trialScores.length
96:       : 0;
97:   const consistency = Math.max(0, 1 - variance);
98: 
99:   // trialFactor: more trials increases confidence, saturates at 6
100:   const trialFactor = Math.min(1, trials.length / 6);
101: 
102:   return distance * consistency * trialFactor;
103: }
